<?php
require __DIR__ . '/../app/bootstrap.php';
$u=require_role(['owner','admin']);$msg=null;$error=null;
try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';
 if($a==='create'){ $code=strtoupper(trim((string)$_POST['code']));$type=in_array($_POST['type']??'', ['percent','fixed'],true)?$_POST['type']:'percent';$value=(float)$_POST['value'];if($code===''||$value<=0)throw new RuntimeException('Coupon code and value are required.');if($type==='percent'&&$value>100)throw new RuntimeException('Percent coupon cannot exceed 100%.');$max=$_POST['max_uses']!==''?(int)$_POST['max_uses']:null;$db->prepare('INSERT INTO coupons(code,type,value,max_uses,starts_at,expires_at,active,created_by) VALUES(?,?,?,?,?,?,1,?)')->execute([$code,$type,$value,$max,$_POST['starts_at']?:null,$_POST['expires_at']?:null,$u['id']]);$msg='Coupon created.';}
 if($a==='toggle'){$id=(int)$_POST['id'];$db->prepare('UPDATE coupons SET active=1-active WHERE id=?')->execute([$id]);$msg='Coupon status updated.';}
}}catch(Throwable $e){$error=$e->getCode()==='23000'?'Coupon code already exists.':$e->getMessage();}
$rows=$db->query('SELECT c.*,u.name creator FROM coupons c LEFT JOIN users u ON u.id=c.created_by ORDER BY c.id DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coupons — SkyNoc</title><style>*{box-sizing:border-box}body{margin:0;background:#f6f8fb;font-family:Inter,system-ui,sans-serif;color:#0f172a}.nav{background:#111827;color:#fff;padding:15px 5%;display:flex;justify-content:space-between}.nav a{color:#fff}.wrap{max-width:1100px;margin:25px auto;padding:0 14px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:16px;padding:18px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}input,select,button{width:100%;padding:11px;border:1px solid #dbe2ea;border-radius:9px;margin:5px 0}button{background:#111827;color:#fff;border:0;font-weight:700}.msg{background:#ecfdf5;color:#166534;padding:10px}.err{background:#fef2f2;color:#991b1b;padding:10px}.table{overflow:auto}table{width:100%;min-width:800px;border-collapse:collapse}td,th{padding:10px;border-bottom:1px solid #eef2f7;text-align:left}@media(max-width:700px){.nav{flex-direction:column;gap:8px}.grid{grid-template-columns:1fr}}</style></head><body><div class="nav"><b>SkyNoc Coupons</b><span><?=e($u['name'])?> · <a href="/admin">Admin</a> · <a href="/logout">Logout</a></span></div><main class="wrap"><h1>Coupons</h1><?php if($msg):?><p class="msg"><?=e($msg)?></p><?php endif;?><?php if($error):?><p class="err"><?=e($error)?></p><?php endif;?><div class="card"><h3>Create Coupon</h3><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="create"><div class="grid"><input name="code" placeholder="WELCOME10" required><select name="type"><option value="percent">Percent</option><option value="fixed">Fixed USD</option></select><input name="value" type="number" min="0.01" step="0.01" placeholder="Value" required><input name="max_uses" type="number" min="1" placeholder="Max uses (optional)"><input name="starts_at" type="datetime-local"><input name="expires_at" type="datetime-local"></div><button>Create Coupon</button></form></div><div class="card"><div class="table"><table><tr><th>Code</th><th>Discount</th><th>Uses</th><th>Validity</th><th>Status</th><th>Action</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b></td><td><?=e($r['type'])==='percent'?number_format((float)$r['value'],2).'%':'$'.number_format((float)$r['value'],2)?></td><td><?=$r['used_count']?> / <?=e((string)($r['max_uses']??'∞'))?></td><td><?=e((string)($r['starts_at']??'Any'))?> → <?=e((string)($r['expires_at']??'Any'))?></td><td><?=((int)$r['active'])?'Active':'Disabled'?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button><?=((int)$r['active'])?'Disable':'Enable'?></button></form></td></tr><?php endforeach;?></table></div></div></main></body></html>